      : ageHours < 200 ? (r < 0.5 ? 'processing' : 'shipped')
      : r < 0.3 ? 'shipped' : 'delivered';

    return {
      id: String(10480 - i),
      customer: `${first} ${surname}`,
      email: `${translit(first)}.${translit(last)}@example.ru`,
      createdAt: new Date(now - ageHours * 3600_000).toISOString(),
